def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_row = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep_row is not None:
        panel = grid[:sep_row]
    else:
        sep_col = next(c for c in range(w)
                       if len({grid[r][c] for r in range(h)}) == 1)
        panel = [row[:sep_col] for row in grid]

    from collections import Counter
    counts = Counter(x for row in panel for x in row)
    bg = counts.most_common(1)[0][0]
    return [[bg if x == bg else 3 for x in row] for row in panel]
